-- Authorization regression suite. Run as postgres; every fixture is rolled back.
begin;
insert into auth.users(id) values ('10000000-0000-4000-8000-000000000001');
insert into auth.sessions(id,user_id,aal) values ('10000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','aal2');
insert into public.portal_roles values ('10000000-0000-4000-8000-000000000001','student');
insert into auth.users(id) values ('10000000-0000-4000-8000-000000000002');
insert into auth.sessions(id,user_id,aal) values ('10000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002','aal2');
insert into public.portal_roles values ('10000000-0000-4000-8000-000000000002','student');
insert into auth.users(id) values ('10000000-0000-4000-8000-000000000003');
insert into auth.sessions(id,user_id,aal) values ('10000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000003','aal2');
insert into public.portal_roles values ('10000000-0000-4000-8000-000000000003','professor');
insert into auth.users(id) values ('10000000-0000-4000-8000-000000000004');
insert into auth.sessions(id,user_id,aal) values ('10000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000004','aal2');
insert into public.portal_roles values ('10000000-0000-4000-8000-000000000004','professor');
insert into auth.users(id) values ('10000000-0000-4000-8000-000000000005');
insert into auth.sessions(id,user_id,aal) values ('10000000-0000-4000-8000-000000000005','10000000-0000-4000-8000-000000000005','aal2');
insert into public.portal_offerings(id,title,professor_id) values ('20000000-0000-4000-8000-000000000001','RLS fixture one','10000000-0000-4000-8000-000000000003'),('20000000-0000-4000-8000-000000000002','RLS fixture two','10000000-0000-4000-8000-000000000004');
insert into public.portal_enrollments values ('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001'),('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000002'),('20000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002');
insert into public.portal_records(offering_id,student_id,kind,label,value) select offering_id,student_id,'grade','Test','70' from public.portal_enrollments;
set local role anon;
do $test$ begin begin perform * from public.portal_records; raise exception 'Anonymous access accepted'; exception when insufficient_privilege then null; end; end $test$;
reset role;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1","session_id":"10000000-0000-4000-8000-000000000001","user_metadata":{"role":"professor"}}',true);
set local role authenticated;
do $test$ begin if not ((select count(*) from public.portal_records)=0) then raise exception 'AAL1 bypass'; end if; end $test$;
do $test$ begin if not (public.portal_access() is null) then raise exception 'AAL1 role leak'; end if; end $test$;
reset role;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2","session_id":"10000000-0000-4000-8000-000000000001","user_metadata":{"role":"professor"}}',true);
set local role authenticated;
do $test$ begin if not (public.portal_access()='student') then raise exception 'Metadata escalation'; end if; end $test$;
do $test$ begin if not ((select count(*) from public.portal_records)=1) then raise exception 'Student isolation'; end if; end $test$;
do $test$ begin if not (not exists(select 1 from public.portal_records where student_id='10000000-0000-4000-8000-000000000002')) then raise exception 'Other student leaked'; end if; end $test$;
do $test$ begin begin update public.portal_roles set role='professor'; raise exception 'Role escalation accepted'; exception when insufficient_privilege then null; end; end $test$;
do $test$ begin begin insert into public.portal_roles values ('10000000-0000-4000-8000-000000000005','professor'); raise exception 'Self provisioning accepted'; exception when insufficient_privilege then null; end; end $test$;
do $test$ begin begin insert into public.portal_records(offering_id,student_id,kind,label,value) values ('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','grade','Attack','100'); raise exception 'Student write accepted'; exception when insufficient_privilege then null; end; end $test$;
do $test$ declare affected integer; begin update public.portal_records set value='100'; get diagnostics affected=row_count; if affected<>0 then raise exception 'Student update accepted'; end if; end $test$;
reset role;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2","session_id":"10000000-0000-4000-8000-000000000003","user_metadata":{"role":"professor"}}',true);
set local role authenticated;
do $test$ begin if not ((select count(*) from public.portal_records)=2) then raise exception 'Professor offering isolation'; end if; end $test$;
do $test$ declare affected integer; begin update public.portal_records set value='71'; get diagnostics affected=row_count; if affected<>2 then raise exception 'Professor update scope'; end if; end $test$;
do $test$ begin begin insert into public.portal_records(offering_id,student_id,kind,label,value) values ('20000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002','grade','Attack','100'); raise exception 'Professor cross offering insert'; exception when insufficient_privilege then null; end; end $test$;
do $test$ begin begin update public.portal_records set offering_id='20000000-0000-4000-8000-000000000002'; raise exception 'Professor cross offering move'; exception when insufficient_privilege then null; end; end $test$;
reset role;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal1","session_id":"10000000-0000-4000-8000-000000000003","user_metadata":{"role":"professor"}}',true);
set local role authenticated;
do $test$ begin if not ((select count(*) from public.portal_records)=0) then raise exception 'Professor MFA bypass'; end if; end $test$;
reset role;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000005","role":"authenticated","aal":"aal2","session_id":"10000000-0000-4000-8000-000000000005","user_metadata":{"role":"professor"}}',true);
set local role authenticated;
do $test$ begin if not (public.portal_access() is null) then raise exception 'Unassigned access'; end if; end $test$;
do $test$ begin if not ((select count(*) from public.portal_records)=0) then raise exception 'Unassigned records'; end if; end $test$;
reset role;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2","session_id":"10000000-0000-4000-8000-000000000003","user_metadata":{"role":"professor"}}',true);
set local role authenticated;
do $test$ begin if not (public.portal_access() is null) then raise exception 'Session identity mismatch'; end if; end $test$;
reset role; delete from auth.sessions where user_id='10000000-0000-4000-8000-000000000001';
reset role;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2","session_id":"10000000-0000-4000-8000-000000000001","user_metadata":{"role":"professor"}}',true);
set local role authenticated;
do $test$ begin if not (public.portal_access() is null) then raise exception 'Revoked session replay'; end if; end $test$;
do $test$ begin if not ((select count(*) from public.portal_records)=0) then raise exception 'Signed out records leaked'; end if; end $test$;
reset role; update auth.sessions set not_after=now()-interval '1 minute' where user_id='10000000-0000-4000-8000-000000000002';
reset role;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2","session_id":"10000000-0000-4000-8000-000000000002","user_metadata":{"role":"professor"}}',true);
set local role authenticated;
do $test$ begin if not (public.portal_access() is null) then raise exception 'Expired session accepted'; end if; end $test$;
reset role; rollback; select 'PASS: anonymous, MFA, ownership, role escalation, professor scope, session replay and expiry' as authorization_tests;
